        """Discard one failed job and its locally queued source file."""
        job = jobs.get(job_id)
        if job is None:
            raise HTTPException(status_code=404, detail="Upload job not found.")
        if not jobs.discard_failed(job_id):
            raise HTTPException(
                status_code=409,
                detail="Only failed upload jobs can be removed.",
            )

